pub struct OrderFacade {
    pricing: Arc<dyn Pricing>,
    inventory: Arc<dyn Inventory>,
    repo: Arc<dyn OrderRepo>,
}
impl OrderFacade {
    pub fn place_order(&self, req: PlaceOrderRequest) -> Result<OrderId, FacadeError> {
        let quote = self.pricing.quote(&req.sku, req.qty)?;   // coarse-grained workflow
        self.inventory.reserve(&req.sku, req.qty)?;
        self.repo.insert(req.customer_id, quote)              // one DB transaction
    }
}
